    add(C, new THREE.BoxGeometry(W * 0.98, 0.18, 0.12), 0, 0.42, L / 2 + 0.04);
    add(C, new THREE.BoxGeometry(W * 0.98, 0.18, 0.12), 0, 0.42, -L / 2 - 0.04);
    add(PL, new THREE.BoxGeometry(0.5, 0.16, 0.03), 0, 0.55, -L / 2 - 0.1);
