      // turn at intersections sometimes
      if (next && next.d < 3 && Math.random() < 0.3) {
        const turnAxis = car.axis === 'x' ? 'z' : 'x';
        const ndir = Math.random() < 0.5 ? 1 : -1;
        car.axis = turnAxis; car.line = next.a; car.dir = ndir;
